<template>
  <div class="menu-bar">
    <div class="dropdown">
      <button @click="toggleDropdown">难易级别</button>
      <ul v-if="dropdownOpen">
        <li @click="setDifficulty('1')">初级</li>
        <li @click="setDifficulty('2')">中级</li>
        <li @click="setDifficulty('3')">高级</li>
      </ul>
    </div>
  </div>
</template>

<script>
export default {
  name: 'MenuBar',
  data() {
    return {
      dropdownOpen: false,
    };
  },
  methods: {
    toggleDropdown() {
      this.dropdownOpen = !this.dropdownOpen;
    },
    setDifficulty(level) {
      this.dropdownOpen = false;
      this.$emit('setDifficulty', level);
    },
  },
};
</script>

<style scoped>
/* 菜单栏样式 */
.menu-bar {
  display: flex;
  justify-content: flex-start;
  align-items: center;
  padding: 10px 20px;
  background-color: #f4f4f4;
  border-bottom: 1px solid #ddd;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  font-family: Arial, sans-serif;
}

/* 按钮样式 */
button {
  padding: 8px 16px;
  font-size: 16px;
  color: #fff;
  background-color: #007bff;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  transition: background-color 0.3s ease, transform 0.2s ease;
}

button:hover {
  background-color: #0056b3;
  transform: translateY(-2px);
}

button:active {
  background-color: #00408f;
  transform: translateY(0);
}

/* 下拉菜单样式 */
.dropdown {
  position: relative;
}

.dropdown ul {
  position: absolute;
  top: 40px;
  left: 0;
  background-color: #fff;
  border: 1px solid #ddd;
  border-radius: 5px;
  list-style: none;
  padding: 10px 0;
  margin: 0;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  z-index: 1000;
}

.dropdown ul li {
  padding: 10px 20px;
  font-size: 16px;
  color: #333;
  cursor: pointer;
  transition: background-color 0.3s ease, color 0.3s ease;
}

.dropdown ul li:hover {
  background-color: #007bff;
  color: #fff;
}

/* 响应式设计 */
@media (max-width: 768px) {
  .menu-bar {
    flex-direction: column;
    align-items: flex-start;
    padding: 10px;
  }

  button {
    width: 100%;
    text-align: center;
    padding: 10px;
  }

  .dropdown ul {
    left: 0;
    width: 100%;
  }

  .dropdown ul li {
    text-align: center;
  }
}
</style>

