<template>
  <div :class="['card', isFaceUp ? 'face-up' : 'face-down']">
    <p v-if="isFaceUp">{{ value }}</p>
  </div>
</template>

<script>
export default {
  name: 'Card',
  props: {
    value: {
      type: String,
      default: 'A', // 默认值为A
    },
    isFaceUp: {
      type: Boolean,
      default: false, // 默认是背面朝上
    },
  },
};
</script>

<style scoped>
.card {
  width: 60px;
  height: 90px;
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #fff;
  border: 1px solid #ccc;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
  font-size: 20px;
  color: #333;
  user-select: none;
}

.face-down {
  background-color: #007700;
  border: 1px solid #004400;
}

.face-up {
  background-color: #fff;
  border: 1px solid #ccc;
}
</style>